export default async function run({ execution_id, input, data }) {
  const get = (key, paramName) => {
    let v;
    try { v = data[key]; } catch (e) { v = undefined; }
    if (v === undefined || v === null || v === "") {
      try { v = input[paramName]; } catch (e) { v = undefined; }
    }
    return v;
  };

  const toArray = v => {
    if (Array.isArray(v)) return v;
    if (typeof v === "string") {
      try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; } catch (e) { return []; }
    }
    return [];
  };

  // Google Sheets returns columns as letters - map them to names
  const CONFIG_COLS = {
    A: "brand_id", B: "brand_name", C: "brand_domain", D: "brand_aliases",
    E: "competitors", F: "engines_enabled", G: "runs_per_prompt",
    H: "sov_alert_threshold", I: "slack_channel", J: "email_to",
    K: "locale", L: "prompt_set_version", M: "active"
  };
  const PROMPT_COLS = {
    A: "brand_id", B: "prompt_id", C: "prompt_text", D: "category",
    E: "locale", F: "active", G: "prompt_version", H: "created_at", I: "notes"
  };

  const remap = (row, cols) => {
    const out = {};
    Object.keys(row || {}).forEach(k => { out[cols[k] || k] = row[k]; });
    return out;
  };

  const brands  = toArray(get("{{$2.result.rows}}", "brandsJson")).map(r => remap(r, CONFIG_COLS));
  const prompts = toArray(get("{{$3.result.data}}", "promptsJson")).map(r => remap(r, PROMPT_COLS));

  const isTrue = v => String(v).trim().toUpperCase() === "TRUE";
  const matrix = [];
  const skipped = [];

  brands.forEach(b => {
    if (!isTrue(b.active)) { skipped.push((b.brand_id || "?") + ": inactive"); return; }

    const own = prompts.filter(p => p.brand_id === b.brand_id && isTrue(p.active));
    if (!own.length) { skipped.push(b.brand_id + ": no active prompts"); return; }

    const engines = String(b.engines_enabled || "perplexity")
      .split("|").map(s => s.trim().toLowerCase()).filter(Boolean);
    const runs = Math.min(Math.max(parseInt(b.runs_per_prompt, 10) || 3, 1), 10);

    own.forEach(p => {
      engines.forEach(engine => {
        for (let i = 1; i <= runs; i++) {
          matrix.push({
            brand_id: b.brand_id,
            brand_name: b.brand_name,
            brand_domain: b.brand_domain,
            brand_aliases: b.brand_aliases,
            competitors: b.competitors,
            prompt_set_version: b.prompt_set_version,
            sov_alert_threshold: b.sov_alert_threshold,
            slack_channel: b.slack_channel,
            email_to: b.email_to,
            prompt_id: p.prompt_id,
            prompt_text: p.prompt_text,
            category: p.category,
            locale: p.locale || b.locale,
            engine: engine,
            run_index: i
          });
        }
      });
    });
  });

  // Repeat 1 for every question and engine runs before any repeat 2. If the run is cut short
  // by the time guard, every question has been asked at least once. The sort is stable, so the
  // brand, question and engine order inside one repeat is unchanged.
  matrix.sort((a, b) => a.run_index - b.run_index);

  const perBrand = {};
  matrix.forEach(m => { perBrand[m.brand_id] = (perBrand[m.brand_id] || 0) + 1; });

  return {
    run_id: "run_" + new Date().toISOString().slice(0, 10) + "_" + String(execution_id).slice(-6),
    started_at: Date.now(),
    total_calls: matrix.length,
    calls_per_brand: perBrand,
    brands_parsed: brands.length,
    prompts_parsed: prompts.length,
    skipped: skipped,
    matrix: matrix
  };
}

