export default async function run({ input, data }) {
  const get = (key, paramName) => {
    let v;
    try { v = data[key]; } catch (e) { v = undefined; }
    if (v === undefined || v === null || v === "") {
      try { v = input[paramName]; } catch (e) { v = undefined; }
    }
    return v;
  };

  const parse = v => {
    if (typeof v !== "string") return v;
    try { return JSON.parse(v); } catch (e) { return v; }
  };

  const engine       = get("{{$6.value.engine}}", "engine") || "";
  const brandAliases = get("{{$6.value.brand_aliases}}", "brandAliases") || "";
  const brandDomain  = get("{{$6.value.brand_domain}}", "brandDomain") || "";
  const competitorsS = get("{{$6.value.competitors}}", "competitors") || "";

  let text = "";
  let urls = [];

  if (engine === "perplexity") {
    // native Perplexity node: content is an object { message: "..." }
    const choices = parse(get("{{$7.result.choices}}", "responseText"));
    const cits = parse(get("{{$7.result.citations}}", "citationsRaw"));
    const arr = Array.isArray(choices) ? choices : [choices];
    const c = arr[0] || {};
    text = String(
      (c.message && c.message.content && c.message.content.message) ||
      (c.message && typeof c.message.content === "string" ? c.message.content : "") ||
      ""
    );
    urls = (Array.isArray(cits) ? cits : [])
      .map(x => typeof x === "string" ? x : ((x && (x.url || x.link)) || ""));

  } else if (engine === "openai" || engine === "claude" || engine === "gemini") {
    // nodes 23, 24, 25 are all All LLM Models - same response shape
    const nodeKey = engine === "openai" ? "{{$23}}"
                  : engine === "claude" ? "{{$24}}"
                  : "{{$25}}";
    const paramName = engine === "openai" ? "openaiRaw"
                    : engine === "claude" ? "claudeRaw"
                    : "geminiRaw";

    const raw = parse(get(nodeKey, paramName)) || {};
    const r = raw.result || raw;

    const choices = r.choices || [];
    (Array.isArray(choices) ? choices : [choices]).forEach(ch => {
      if (!ch) return;
      const msg = ch.message || {};
      const content = msg.content || "";

      if (typeof content === "string") text += content;
      else if (Array.isArray(content)) {
        content.forEach(ct => {
          if (typeof ct === "string") text += ct;
          else if (ct && typeof ct.text === "string") text += ct.text;
        });
      } else if (content && typeof content === "object" && typeof content.message === "string") {
        text += content.message;
      }

      // OpenRouter web search citations
      const ann = msg.annotations || [];
      (Array.isArray(ann) ? ann : []).forEach(a => {
        if (!a) return;
        const u = a.url || (a.url_citation && a.url_citation.url);
        if (u) urls.push(u);
      });
    });

    const cits = r.citations || [];
    (Array.isArray(cits) ? cits : []).forEach(x => {
      if (!x) return;
      const u = typeof x === "string" ? x : (x.url || x.link || "");
      if (u) urls.push(u);
    });

    if (!text) text = String(r.text || r.output_text || "");
  }

  // the same link arrives in both annotations and citations - drop duplicates
  urls = urls.filter(Boolean).filter((u, i, a) => a.indexOf(u) === i);

  const domains = urls.map(u => {
    try { return new URL(u).hostname.replace("www.", ""); } catch (e) { return ""; }
  }).filter(Boolean);

  const lower = text.toLowerCase();
  const aliases = String(brandAliases)
    .split("|").map(s => s.trim().toLowerCase()).filter(Boolean);
  const competitors = String(competitorsS)
    .split("|").map(s => s.trim()).filter(Boolean);

  // word-boundary match without escaped regex
  const found = needle => {
    const n = String(needle).toLowerCase();
    if (!n) return false;
    const isLetter = ch => /[a-z0-9]/.test(ch);
    let from = 0;
    while (true) {
      const i = lower.indexOf(n, from);
      if (i < 0) return false;
      const before = i === 0 ? " " : lower[i - 1];
      const after = i + n.length >= lower.length ? " " : lower[i + n.length];
      if (!isLetter(before) && !isLetter(after)) return true;
      from = i + 1;
    }
  };

  const brandMentioned = aliases.some(a => found(a));
  const brandDomainCited = domains.some(d =>
    d.indexOf(String(brandDomain).toLowerCase()) >= 0);
  const competitorsFound = competitors.filter(x => found(x));

  let brandPosition = null;
  if (brandMentioned) {
    let bi = Number.MAX_SAFE_INTEGER;
    aliases.forEach(a => {
      const i = lower.indexOf(a);
      if (i >= 0 && i < bi) bi = i;
    });
    const order = [{ who: "brand", at: bi }];
    competitorsFound.forEach(x => {
      order.push({ who: x, at: lower.indexOf(x.toLowerCase()) });
    });
    order.sort((a, b) => a.at - b.at);
    brandPosition = order.findIndex(o => o.who === "brand") + 1;
  }

  return {
    engine: engine,
    grounded: urls.length > 0,
    brand_mentioned: brandMentioned,
    brand_domain_cited: brandDomainCited,
    brand_position: brandPosition,
    competitors_found: competitorsFound,
    citations: domains,
    confidence: brandDomainCited ? "high" : (brandMentioned ? "needs_judge" : "none"),
    response_excerpt: text.slice(0, 500),
    _debug: { engine: engine, text_len: text.length, cit_count: urls.length }
  };
}

