export default async function run({ execution_id, input, data, store }) {
  const get = (key, paramName) => {
    let v;
    try { v = data[key]; } catch (e) { v = undefined; }
    if (v === undefined || v === null || v === "") {
      try { v = input[paramName]; } catch (e) { v = undefined; }
    }
    return v;
  };

  let n = get("{{$8}}", "normalized");
  if (typeof n === "string") {
    try { n = JSON.parse(n); } catch (e) { n = {}; }
  }
  n = n || {};

  const KEY = "geo_acc_" + execution_id;
  const acc = (await store.getGlobalVariable(KEY)) || [];

  acc.push({
    brand_id: get("{{$6.value.brand_id}}", "brandId") || "",
    prompt_id: get("{{$6.value.prompt_id}}", "promptId") || "",
    category: get("{{$6.value.category}}", "category") || "",
    prompt_text: get("{{$6.value.prompt_text}}", "promptText") || "",
    run_index: parseInt(get("{{$6.value.run_index}}", "runIndex"), 10) || 1,
    prompt_set_version: get("{{$6.value.prompt_set_version}}", "promptSetVersion") || "v1",
    engine: n.engine || "",
    grounded: n.grounded === true,
    brand_mentioned: n.brand_mentioned === true,
    brand_domain_cited: n.brand_domain_cited === true,
    brand_position: n.brand_position === undefined ? null : n.brand_position,
    competitors_found: n.competitors_found || [],
    citations: n.citations || [],
    confidence: n.confidence || "none",
    response_excerpt: n.response_excerpt || ""
  });

  await store.setGlobalVariable(KEY, acc);

  const last = acc[acc.length - 1];
  return {
    collected: acc.length,
    last_brand: last.brand_id,
    last_engine: last.engine,
    last_category: last.category
  };
}

