export default async function run({ execution_id, input, data, store }) {
  const KEY = "geo_acc_" + execution_id;
  const acc = (await store.getGlobalVariable(KEY)) || [];

  let runId;
  try { runId = data["{{$4.run_id}}"]; } catch (e) { runId = undefined; }
  if (!runId) { try { runId = input.runId; } catch (e) {} }

  const ts = new Date().toISOString();
  const run_id = runId || ("run_" + ts.slice(0, 10));

  const bool = v => v === true ? "TRUE" : "FALSE";
  const join = v => Array.isArray(v) ? v.join("|") : "";
  const val = v => (v === undefined || v === null) ? "" : v;

  // order must match results_log columns A..P
  const rows = acc.map(r => ([
    val(r.brand_id),                 // A brand_id
    run_id,                          // B run_id
    ts,                              // C timestamp
    val(r.prompt_id),                // D prompt_id
    val(r.engine),                   // E engine
    r.run_index || 1,                // F run_index
    bool(r.grounded),                // G grounded
    bool(r.brand_mentioned),         // H brand_mentioned
    val(r.brand_position),           // I brand_position
    bool(r.brand_domain_cited),      // J brand_domain_cited
    val(r.sentiment_score),          // K sentiment_score
    val(r.confidence),               // L confidence
    join(r.competitors_found),       // M competitors_found
