export default async function run({ input, data }) {
  const get = (key, paramName) => {
    let v;
    try { v = data[key]; } catch (e) { v = undefined; }
    if (v === undefined || v === null || v === "") {
      try { v = input[paramName]; } catch (e) { v = undefined; }
    }
    return v;
  };

  const parse = v => {
    if (typeof v !== "string") return v;
    try { return JSON.parse(v); } catch (e) { return []; }
  };

  const brandId      = get("{{$15.value.brand_id}}", "brandId") || "";
  const brandName    = get("{{$15.value.brand_name}}", "brandName") || brandId;
  const brandDomain  = String(get("{{$15.value.brand_domain}}", "brandDomain") || "").toLowerCase();
  const version      = get("{{$15.value.prompt_set_version}}", "promptSetVersion") || "v1";
  const competitorsS = get("{{$15.value.competitors}}", "competitors") || "";
  const rowsRaw      = parse(get("{{$15.value.rows}}", "rowsJson")) || [];
  const list = Array.isArray(rowsRaw) ? rowsRaw : [];

  const round = (x, d) => Math.round(x * Math.pow(10, d)) / Math.pow(10, d);
  const rate = (a, b) => b > 0 ? round(a / b, 3) : "";

  // branded prompts measure brand knowledge, the rest measure visibility
  const isBranded = r => String(r.category || "").toLowerCase() === "brand_research";

  // ---------- per-engine metrics ----------
  const byEngine = {};
  list.forEach(r => {
    const e = r.engine || "unknown";
    if (!byEngine[e]) {
      byEngine[e] = {
        n: 0, mentions: 0, cited: 0, posSum: 0, posN: 0, compMentions: 0,
        ub_n: 0, ub_m: 0, br_n: 0, br_m: 0
      };
    }
    const s = byEngine[e];
    const mentioned = r.brand_mentioned === true;
    s.n++;
    if (mentioned) s.mentions++;
    if (r.brand_domain_cited === true) s.cited++;
    if (r.brand_position) { s.posSum += Number(r.brand_position); s.posN++; }
    s.compMentions += (r.competitors_found || []).length;

    if (isBranded(r)) { s.br_n++; if (mentioned) s.br_m++; }
    else { s.ub_n++; if (mentioned) s.ub_m++; }
  });

  const metrics = Object.keys(byEngine).map(engine => {
    const s = byEngine[engine];
    return {
      brand_id: brandId,
      engine: engine,
      prompt_set_version: version,
      responses: s.n,
      mention_rate: rate(s.mentions, s.n),
      share_of_voice: rate(s.mentions, Math.max(1, s.mentions + s.compMentions)),
      citation_rate: rate(s.cited, s.n),
      avg_position: s.posN ? round(s.posSum / s.posN, 2) : "",
      avg_sentiment: "",
      visibility: rate(s.ub_m, s.ub_n),
      brand_knowledge: rate(s.br_m, s.br_n)
    };
  });

  // ---------- competitor board, unbranded answers only ----------
  const unbranded = list.filter(r => !isBranded(r));
  const ubTotal = unbranded.length;

  const competitors = String(competitorsS)
    .split("|").map(s => s.trim()).filter(Boolean);

  const counts = {};
  counts[brandName] = unbranded.filter(r => r.brand_mentioned === true).length;
  competitors.forEach(c => { counts[c] = 0; });
  unbranded.forEach(r => {
    (r.competitors_found || []).forEach(c => { counts[c] = (counts[c] || 0) + 1; });
  });

  const competitorBoard = Object.keys(counts).map(name => ({
    name: name,
    mentions: counts[name],
    rate: rate(counts[name], ubTotal),
    is_brand: name === brandName
  })).sort((a, b) => b.mentions - a.mentions);

  // ---------- sources the engines cite ----------
  const topCount = {};
  const gapCount = {};
  unbranded.forEach(r => {
    const seen = {};
    const hasCompetitor = (r.competitors_found || []).length > 0;
    const hasBrand = r.brand_mentioned === true;
    (r.citations || []).forEach(d => {
      if (!d || seen[d]) return;
      seen[d] = 1;
      topCount[d] = (topCount[d] || 0) + 1;
      // competitor present, brand absent - a source worth targeting
      if (hasCompetitor && !hasBrand) gapCount[d] = (gapCount[d] || 0) + 1;
    });
  });

  const isOwn = d => brandDomain && d.indexOf(brandDomain) >= 0;

  const topSources = Object.keys(topCount)
    .map(d => ({ domain: d, responses: topCount[d], is_own: isOwn(d) }))
    .sort((a, b) => b.responses - a.responses)
    .slice(0, 15);

  const gapSources = Object.keys(gapCount)
    .filter(d => !isOwn(d))
    .map(d => ({ domain: d, responses: gapCount[d] }))
    .sort((a, b) => b.responses - a.responses)
    .slice(0, 15);

  return {
    brand_id: brandId,
    brand_name: brandName,
    engine_count: metrics.length,
    unbranded_responses: ubTotal,
    branded_responses: list.length - ubTotal,
    metrics: metrics,
    competitor_board: competitorBoard,
    top_sources: topSources,
    gap_sources: gapSources
  };
}

