export default async function run({ input, data }) {
  const get = (key, paramName) => {
    let v;
    try { v = data[key]; } catch (e) { v = undefined; }
    if (v === undefined || v === null || v === "") {
      try { v = input[paramName]; } catch (e) { v = undefined; }
    }
    return v;
  };

  const parse = v => {
    if (typeof v !== "string") return v;
    try { return JSON.parse(v); } catch (e) { return []; }
  };

  const cur = parse(get("{{$16.metrics}}", "currentJson")) || [];
  const prevRaw = parse(get("{{$17.result.data}}", "previousJson")) || [];
  const version = get("{{$15.value.prompt_set_version}}", "version") || "v1";
  const runId = get("{{$15.value.run_id}}", "runId") || "";
  const threshold = (parseFloat(get("{{$15.value.sov_alert_threshold}}", "threshold")) || 5) / 100;

  // metrics_history comes back with letter keys
  const COLS = {
    A: "brand_id", B: "run_id", C: "timestamp", D: "engine",
    E: "prompt_set_version", F: "responses", G: "mention_rate",
    H: "share_of_voice", I: "citation_rate", J: "avg_position",
    K: "avg_sentiment", L: "wow_delta_sov", M: "alert_fired",
    N: "visibility", O: "brand_knowledge"
  };

  // drop junk rows and rows from the current run
  const prev = (Array.isArray(prevRaw) ? prevRaw : []).map(row => {
    const out = {};
    Object.keys(row || {}).forEach(k => { out[COLS[k] || k] = row[k]; });
    return out;
  }).filter(p =>
    p.brand_id &&
    String(p.run_id || "").indexOf("run_") === 0 &&
    String(p.run_id) !== String(runId) &&
    !isNaN(parseFloat(p.share_of_voice))
  );

  // Sheets may return "12.5%" or 0.125
  const num = v => {
    if (v === undefined || v === null || v === "") return null;
    const s = String(v);
    const x = parseFloat(s.replace("%", ""));
    if (isNaN(x)) return null;
    return s.indexOf("%") >= 0 ? x / 100 : x;
  };

  // latest row per engine within the same prompt set version
  const last = {};
  prev.forEach(p => {
    if (String(p.prompt_set_version) !== String(version)) return;
    const t = Date.parse(p.timestamp || 0) || 0;
    if (!last[p.engine] || t > last[p.engine]._t) {
      last[p.engine] = {
        sov: num(p.share_of_voice),
        cit: num(p.citation_rate),
        vis: num(p.visibility),
        _t: t
      };
    }
  });

  const alerts = [];
  const out = (Array.isArray(cur) ? cur : []).map(m => {
    const L = last[m.engine];
    const sovBefore = L ? L.sov : null;
    const delta = sovBefore === null ? "" : Math.round((m.share_of_voice - sovBefore) * 1000) / 1000;

    if (L && L.vis !== null && m.visibility !== "" && (m.visibility - L.vis) <= -threshold) {
      alerts.push(m.engine + ": visibility down " + Math.abs((m.visibility - L.vis) * 100).toFixed(1) + " pp");
    }
    if (L && L.cit !== null && L.cit > 0 && m.citation_rate === 0) {
      alerts.push(m.engine + ": lost all citations");
    }

    const copy = {};
    Object.keys(m).forEach(k => { copy[k] = m[k]; });
    copy.run_id = runId;
    copy.wow_delta_sov = delta;
    return copy;
  });

  const fired = alerts.length > 0;
  out.forEach(m => { m.alert_fired = fired ? "TRUE" : "FALSE"; });

  return { metrics: out, alerts: alerts, alert_fired: fired };
}

