export default async function run({ input, data }) {
  const get = (key, paramName) => {
    let v;
    try { v = data[key]; } catch (e) { v = undefined; }
    if (v === undefined || v === null || v === "") {
      try { v = input[paramName]; } catch (e) { v = undefined; }
    }
    return v;
  };

  const parse = v => {
    if (typeof v !== "string") return v;
    try { return JSON.parse(v); } catch (e) { return []; }
  };

  const board       = parse(get("{{$16.competitor_board}}", "boardJson")) || [];
  const gaps        = parse(get("{{$45.stable_gap_sources}}", "gapJson")) || [];
  const metrics     = parse(get("{{$16.metrics}}", "metricsJson")) || [];
  const alerts      = parse(get("{{$18.alerts}}", "alertsJson")) || [];
  const brandName   = get("{{$16.brand_name}}", "brandName") || "";
  const brandDomain = get("{{$15.value.brand_domain}}", "brandDomain") || "";
  const competitors = get("{{$15.value.competitors}}", "competitors") || "";
  const unbranded   = get("{{$16.unbranded_responses}}", "unbranded") || 0;

  const pct = v => {
    if (v === "" || v === null || v === undefined) return "n/a";
    return (Math.round(Number(v) * 1000) / 10) + "%";
  };

  const now = new Date();
  const year = now.getFullYear();
  const today = now.toISOString().slice(0, 10);

  const compList = String(competitors).split("|").map(s => s.trim()).filter(Boolean);

  // flag competitor-owned domains - the model kept treating them as pitch targets
  const compDomains = {};
  compList.forEach(c => {
    const slug = c.toLowerCase().replace(/[^a-z0-9]/g, "");
    if (slug) compDomains[slug] = c;
  });
  const ownedBy = domain => {
    const d = String(domain).toLowerCase();
    const keys = Object.keys(compDomains);
    for (let i = 0; i < keys.length; i++) {
      if (d.indexOf(keys[i]) === 0 || d.indexOf("." + keys[i]) >= 0) return compDomains[keys[i]];
    }
    return null;
  };

  const engineLines = (Array.isArray(metrics) ? metrics : []).map(m =>
    "- " + m.engine + ": visibility " + pct(m.visibility) +
    ", brand knowledge " + pct(m.brand_knowledge) +
    ", citation rate " + pct(m.citation_rate)
  );

  const boardLines = (Array.isArray(board) ? board : []).map(b =>
    "- " + b.name + (b.is_brand ? " (THIS BRAND)" : "") +
    ": " + b.mentions + " mentions, " + pct(b.rate)
  );

  const gapLines = (Array.isArray(gaps) ? gaps : []).slice(0, 15).map(g => {
    const owner = ownedBy(g.domain);
    const tag = owner ? "  [OWNED BY COMPETITOR " + owner + " - DO NOT PITCH]" : "";
    const n = g.answers_total !== undefined ? g.answers_total : g.responses;
    const seen = g.runs_seen !== undefined ? ", seen in " + g.runs_seen + " of the last runs" : "";
    return "- " + g.domain + ": cited in " + n + " answers" + seen + tag;
  });

  const alertLines = (Array.isArray(alerts) && alerts.length)
    ? alerts.map(a => "- " + a)
    : ["- none"];

  const prompt = [
    "You are a GEO (generative engine optimization) analyst. Write a weekly action plan for one brand, based only on the measurement data below.",
    "",
    "BRAND: " + brandName + " (" + brandDomain + ")",
    "COMPETITORS: " + compList.join(", "),
    "UNBRANDED ANSWERS MEASURED: " + unbranded,
    "TODAY: " + today,
    "CURRENT YEAR: " + year,
    "",
    "HOW TO READ THE METRICS",
    "- visibility = share of answers to unbranded questions that mention the brand. This is the headline metric.",
    "- brand knowledge = share of answers to questions that name the brand directly.",
    "- High knowledge with low visibility means the engines know the brand but do not recommend it unprompted.",
    "",
    "VISIBILITY BY ENGINE",
    engineLines.join("\n"),
    "",
    "WHO THE ENGINES RECOMMEND IN UNBRANDED ANSWERS",
    boardLines.join("\n"),
    "",
    "SOURCES THE ENGINES CITE WHERE COMPETITORS APPEAR BUT THIS BRAND DOES NOT",
    gapLines.join("\n"),
    "",
    "ALERTS THIS WEEK",
    alertLines.join("\n"),
    "",
    "ACTION TYPES - pick exactly one per action, and it must match what the action actually does:",
    "  community  - publish tutorials, code examples or open-source repos on a developer platform. target = that platform.",
    "  directory  - submit or improve a listing in a software catalogue. target = that catalogue.",
    "  listicle   - contact the owner of a third-party article or site to be included in THEIR content. target = that third-party domain.",
    "  comparison - build a page on the brand's own site comparing it to a named competitor. target = " + brandDomain + " ONLY.",
    "  faq        - add question-and-answer content on the brand's own site. target = " + brandDomain + " ONLY.",
    "  entity     - fix structured data, Wikipedia, Wikidata or knowledge-panel presence. target = that property.",
    "",
    "HARD RULES - breaking any of these makes the answer unusable:",
    "1. Every action must cite a specific domain or number from the data above. No generic SEO advice.",
    "2. The type must match the target. If the target is " + brandDomain + ", the type is comparison, faq or entity - never listicle or community. If the target is a third-party domain, the type is listicle, community, directory or entity - never comparison.",
    "3. Never propose publishing a roundup, listicle or 'best tools' article on " + brandDomain + " or its blog. The engines cite third-party sources, not the brand's own blog. Such an article will not move visibility. If a listicle domain appears in the data, the action is to pitch for inclusion in THAT domain's existing article.",
    "4. Domains marked [OWNED BY COMPETITOR] must never be a pitch target. Use them only as evidence that comparison pages on " + brandDomain + " are needed.",
    "5. Any year you write must be " + year + ". Never write a different year.",
    "6. Prioritise by how many answers a source appears in.",
    "7. Give 4 to 6 actions. Priority 1 is the single highest-leverage step.",
    "8. If visibility is zero on every engine, say so plainly in the diagnosis.",
    "",
    "Return strict JSON only. No text before or after. No code fences.",
    "{",
    "  \"headline\": \"one sentence, max 20 words\",",
    "  \"diagnosis\": \"2-3 sentences on the gap between knowledge and visibility\",",
    "  \"actions\": [",
    "    {\"priority\": 1, \"type\": \"community|directory|listicle|comparison|faq|entity\", \"target\": \"domain or page\", \"action\": \"what to do, one or two sentences\", \"evidence\": \"the number from the data that justifies it\"}",
    "  ]",
    "}"
  ].join("\n");

  return { prompt: prompt, prompt_len: prompt.length };
}

