export default async function run({ input, data }) {
  // values arrive either from node params or straight from data by substitution key
  const get = (key, paramName) => {
    let v;
    try { v = data[key]; } catch (e) { v = undefined; }
    if (v === undefined || v === null || v === "") {
      try { v = input[paramName]; } catch (e) { v = undefined; }
    }
    return v;
  };

  const parse = v => {
    if (typeof v !== "string") return v;
    try { return JSON.parse(v); } catch (e) { return v; }
  };

  const brandId   = get("{{$15.value.brand_id}}", "brandId") || "";
  const brandName = get("{{$16.brand_name}}", "brandName") || "";
  const runId     = get("{{$15.value.run_id}}", "runId") || "";

  // node 27 response - try every possible key, no declared param needed
  let raw;
  const candidates = [
    "{{$27}}",
    "{{$27.result}}",
    "{{$27.result.choices}}",
    "{{ $27 }}"
  ];
  for (let i = 0; i < candidates.length; i++) {
    let v;
    try { v = data[candidates[i]]; } catch (e) { v = undefined; }
    if (v !== undefined && v !== null && v !== "") { raw = v; break; }
  }
  if (raw === undefined) { try { raw = input.llmRaw; } catch (e) {} }
  raw = parse(raw) || {};

  const r = raw.result || raw;
  const choices = Array.isArray(r) ? r : (r.choices || []);
  const c0 = (Array.isArray(choices) ? choices : [choices])[0] || {};
  const msg = c0.message || c0 || {};

  let rec = null;
  let parsedOk = false;
  let rawLen = 0;

  // Latenode parses the model JSON itself and puts the object in content
  if (msg.content && typeof msg.content === "object" && !Array.isArray(msg.content)) {
    if (msg.content.actions || msg.content.headline) {
      rec = msg.content;
      parsedOk = true;
    }
  }

  // fallback: plain string, block array, or content_raw inside code fences
  if (!rec) {
    let text = "";
    if (typeof msg.content === "string") text = msg.content;
    else if (Array.isArray(msg.content)) {
      msg.content.forEach(x => {
        if (typeof x === "string") text += x;
        else if (x && typeof x.text === "string") text += x.text;
      });
    }
    if (!text && typeof msg.content_raw === "string") text = msg.content_raw;
    if (!text) text = String(r.text || r.output_text || "");
    rawLen = text.length;

    let jsonStr = text;
    const start = jsonStr.indexOf("{");
    const end = jsonStr.lastIndexOf("}");
    if (start >= 0 && end > start) jsonStr = jsonStr.slice(start, end + 1);

    try { rec = JSON.parse(jsonStr); parsedOk = true; } catch (e) { parsedOk = false; }
    if (!rec || typeof rec !== "object") {
      rec = { headline: "", diagnosis: text.slice(0, 1500), actions: [] };
    }
  }

  const actions = (Array.isArray(rec.actions) ? rec.actions : []).map((x, i) => ({
    priority: Number(x && x.priority) || (i + 1),
    type: String((x && x.type) || ""),
    target: String((x && x.target) || ""),
    action: String((x && x.action) || ""),
    evidence: String((x && x.evidence) || "")
  })).sort((a, b) => a.priority - b.priority);

  const lines = [];
  if (rec.headline) lines.push(String(rec.headline));
  if (rec.diagnosis) { lines.push(""); lines.push(String(rec.diagnosis)); }
  if (actions.length) {
    lines.push("");
    lines.push("What to do next:");
    actions.forEach((a, i) => {
      lines.push((i + 1) + ". " + (a.target ? "[" + a.target + "] " : "") + a.action);
      if (a.evidence) lines.push("   Why: " + a.evidence);
    });
  }

  return {
    brand_id: brandId,
    brand_name: brandName,
    run_id: runId,
    parsed_ok: parsedOk,
    headline: String(rec.headline || ""),
    diagnosis: String(rec.diagnosis || ""),
    actions: actions,
    report_text: lines.join("\n"),
    _debug: { actions_n: actions.length, raw_len: rawLen }
  };
}

