    const valStyle = b.is_brand ? "font-weight:700;color:#1a73e8" : "";
    return "<tr>" +
      "<td style='" + TD + ";" + nameStyle + "'>" + esc(b.name) + (b.is_brand ? " (you)" : "") + "</td>" +
      "<td style='" + TD + ";width:55%'>" +
        "<div style='background:#f1f3f4;border-radius:3px;height:10px'>" +
        "<div style='background:" + barColor + ";width:" + bar + "%;height:10px;border-radius:3px'></div>" +
        "</div>" +
      "</td>" +
      "<td style='" + TD + ";text-align:right;white-space:nowrap;" + valStyle + "'>" + pct(b.rate) + "</td>" +
      "</tr>";
