    "<td style='" + TD + "'>" + plain(g.domain) + "</td>" +
    "<td style='" + TD + ";text-align:right'>" + esc(g.answers_total !== undefined ? g.answers_total : g.responses) + "</td>" +
    "</tr>"
  ).join("");

