        Math.round(Number(serp.google_presence || 0) * 100) + "%</strong> of the same " +
        esc(serp.prompts_checked) + " questions" +
        (serp.avg_google_position ? ", average position <strong>" + esc(serp.avg_google_position) + "</strong>" : "") +
        ". In AI answers it is named in <strong>" + pct(avgVis) + "</strong> of them." +
      "</div>"
    : "";

