      "<div style='font-size:11px;color:#5f6368;text-transform:uppercase;letter-spacing:.4px;margin-bottom:4px'>" +
        esc(a.priority) + " &middot; " + esc(fixType(a)) + " &middot; " + plain(a.target) +
