    ? "<div style='margin:0 0 20px;padding:12px 14px;background:#fef7e0;border-left:3px solid #f9ab00;border-radius:0 4px 4px 0;font-size:13px;color:#3c4043'>" +
        "<strong>Alerts</strong><br>" + alerts.map(a => esc(a)).join("<br>") +
      "</div>"
    : "";

