  "<div style='font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif;max-width:640px;margin:0 auto;color:#202124'>" +

    "<div style='padding:24px 0 16px;border-bottom:2px solid #202124'>" +
      "<div style='font-size:11px;letter-spacing:1.5px;text-transform:uppercase;color:#5f6368'>AI Search Visibility</div>" +
      "<div style='font-size:24px;font-weight:700;margin-top:4px'>" + esc(brandName) + "</div>" +
      "<div style='font-size:13px;color:#5f6368;margin-top:2px'>" + plain(brandDomain) + " &middot; " + dateStr + "</div>" +
    "</div>" +

    "<div style='padding:24px 0;text-align:center;border-bottom:1px solid #e8eaed'>" +
      "<div style='font-size:12px;color:#5f6368;text-transform:uppercase;letter-spacing:.5px'>Visibility</div>" +
      "<div style='font-size:44px;font-weight:700;line-height:1.1;margin:6px 0'>" + pct(avgVis) + "</div>" +
      "<div style='font-size:13px;color:#5f6368'>of " + esc(unbranded) + " answers to unbranded questions mention " + esc(brandName) + "</div>" +
    "</div>" +

    (headline ? "<div style='padding:20px 0 0;font-size:16px;font-weight:600;line-height:1.4'>" + plain(headline) + "</div>" : "") +
    (diagnosis ? "<div style='padding:8px 0 20px;font-size:14px;line-height:1.6;color:#3c4043'>" + plain(diagnosis) + "</div>" : "") +

