      "<div style='font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.6px;color:#5f6368;margin:28px 0 8px'>Sources citing competitors, not you</div>" +
      "<table style='width:100%;border-collapse:collapse'>" +
        "<tr><th style='" + TH + "'>Domain</th><th style='" + TH + ";text-align:right'>Answers</th></tr>" +
        gapRows +
      "</table>" : "") +

    (actionItems ?
      "<div style='font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.6px;color:#5f6368;margin:28px 0 12px'>What to do next</div>" +
      actionItems : "") +

    "<div style='margin-top:28px;padding-top:16px;border-top:1px solid #e8eaed;font-size:11px;color:#9aa0a6;line-height:1.5'>" +
      "Visibility counts answers to questions that do not name the brand. Engines are non-deterministic: " +
      "week-to-week swings under 5 pp are noise, not signal.<br>" +
      "Run " + esc(runId) + " &middot; GEO Radar" +
    "</div>" +

  "</div>";

  const slackLines = [];
  slackLines.push("*GEO Radar - " + brandName + "*");
  if (alerts.length) slackLines.push(":warning: " + alerts.join("\n:warning: "));
  slackLines.push("Visibility: *" + (avgVis === "" ? "n/a" : (Math.round(avgVis * 1000) / 10).toFixed(1) + "%") + "* of " + unbranded + " unbranded answers");
  list.forEach(m => {
    const d = (m.wow_delta_sov === "" || m.wow_delta_sov === null || m.wow_delta_sov === undefined)
      ? "" : " (" + (Number(m.wow_delta_sov) > 0 ? "+" : "") + (Number(m.wow_delta_sov) * 100).toFixed(1) + " pp)";
    slackLines.push("• " + m.engine + ": " + (m.visibility === "" ? "n/a" : (Number(m.visibility) * 100).toFixed(1) + "%") + d);
  });
  if (actions.length) {
    slackLines.push("");
    slackLines.push("*Top action:* " + (actions[0].target ? "[" + actions[0].target + "] " : "") + actions[0].action);
  }

  return {
    subject: "GEO Radar - " + brandName + " - " + dateStr,
    html: html,
    slack_text: slackLines.join("\n"),
    avg_visibility: avgVis,
    has_alerts: (Array.isArray(alerts) && alerts.length > 0)
  };
}

