/** @CustomParams
{
    "llmRaw": {
        "type": "string",
        "title": "LLM Raw",
        "required": true
    },
    "brandId": {
        "type": "string",
        "title": "Brand ID",
        "required": true
    },
    "locale": {
        "type": "string",
        "title": "Locale",
        "required": false
    }
}
*/
export default async function run({ input, data }) {
  const get = (key, paramName) => {
    let v;
    try { v = data[key]; } catch (e) { v = undefined; }
    if (v === undefined || v === null || v === "") {
      try { v = input[paramName]; } catch (e) { v = undefined; }
    }
    return v;
  };

  const parse = v => {
    if (typeof v !== "string") return v;
    try { return JSON.parse(v); } catch (e) { return v; }
  };

  const brandId = get("brandId", "brandId") || "";
  const locale  = get("locale", "locale") || "en-US";

  const raw = parse(get("llmRaw", "llmRaw")) || {};
  const r = raw.result || raw;
  const c0 = ((r.choices || [])[0]) || {};
  const msg = c0.message || {};

  let rec = null;
  if (msg.content && typeof msg.content === "object" && !Array.isArray(msg.content) && msg.content.prompts) {
    rec = msg.content;
  }
  if (!rec) {
    let text = "";
    if (typeof msg.content === "string") text = msg.content;
    else if (typeof msg.content_raw === "string") text = msg.content_raw;
    const s = text.indexOf("{");
    const e = text.lastIndexOf("}");
    if (s >= 0 && e > s) {
      try { rec = JSON.parse(text.slice(s, e + 1)); } catch (err) { rec = null; }
    }
  }
  if (!rec || !Array.isArray(rec.prompts)) rec = { prompts: [] };

  const VALID = ["discovery", "problem_solution", "use_case", "comparison", "expert", "brand_research"];
  const today = new Date().toISOString().slice(0, 10);
  const version = "v" + today.replace(/-/g, "");

  const seen = {};
  const clean = [];
  rec.prompts.forEach(p => {
    if (!p) return;
    const text = String(p.prompt_text || "").trim();
    if (!text || text.length < 10) return;
    const key = text.toLowerCase();
    if (seen[key]) return;
    seen[key] = 1;
    let cat = String(p.category || "").trim().toLowerCase();
    if (VALID.indexOf(cat) < 0) cat = "use_case";
    clean.push({ category: cat, text: text, note: String(p.note || "").slice(0, 60) });
  });

  const order = {};
  VALID.forEach((c, i) => { order[c] = i; });
  clean.sort((a, b) => (order[a.category] - order[b.category]));

  const rows = clean.map((p, i) => ([
    brandId,                                  // A brand_id
    "p" + String(i + 1).padStart(3, "0"),     // B prompt_id
    p.text,                                   // C prompt_text
    p.category,                               // D category
    locale,                                   // E locale
    "TRUE",                                   // F active
    version,                                  // G prompt_version
    today,                                    // H created_at
    p.note                                    // I notes
  ]));

  const byCat = {};
  clean.forEach(p => { byCat[p.category] = (byCat[p.category] || 0) + 1; });
  const branded = clean.filter(p => p.category === "brand_research").length;

  return {
    brand_id: brandId,
    count: rows.length,
    by_category: byCat,
    branded: branded,
    unbranded: rows.length - branded,
    prompt_set_version: version,
    rows: rows
  };
}

