  const brandId = get("{{$15.value.brand_id}}", "brandId") || "";
  const runId   = get("{{$15.value.run_id}}", "runId") || "";
  const ts = new Date().toISOString();

  // gap domains are flagged separately - those feed the recommendations
  const gapSet = {};
  (Array.isArray(gaps) ? gaps : []).forEach(g => { if (g && g.domain) gapSet[g.domain] = 1; });

  const rows = (Array.isArray(top) ? top : []).map(s => ([
