export default async function run({ input, data }) {
  const get = (key, paramName) => {
    let v;
    try { v = data[key]; } catch (e) { v = undefined; }
    if (v === undefined || v === null || v === "") {
      try { v = input[paramName]; } catch (e) { v = undefined; }
    }
    return v;
  };

  const parse = v => {
    if (typeof v !== "string") return v;
    try { return JSON.parse(v); } catch (e) { return []; }
  };

  const raw = parse(get("{{$44.result.data}}", "historyJson")) || [];
  const brandDomain = String(get("{{$15.value.brand_domain}}", "brandDomain") || "").toLowerCase();

  const COLS = { A: "brand_id", B: "run_id", C: "timestamp", D: "domain", E: "responses", F: "is_gap" };
  const rows = (Array.isArray(raw) ? raw : []).map(r => {
    const out = {};
    Object.keys(r || {}).forEach(k => { out[COLS[k] || k] = r[k]; });
    return out;
  });

  // 28-day window
  const cutoff = Date.now() - 28 * 24 * 60 * 60 * 1000;
  const recent = rows.filter(r => {
    const t = Date.parse(r.timestamp || 0);
    return t && t >= cutoff && r.domain;
  });

  // how many runs fall inside the window
  const runs = {};
  recent.forEach(r => { runs[r.run_id] = 1; });
  const runCount = Object.keys(runs).length || 1;

  const agg = {};
  recent.forEach(r => {
    const d = r.domain;
    if (!agg[d]) agg[d] = { domain: d, answers: 0, runs: {}, gapRuns: {} };
    agg[d].answers += parseInt(r.responses, 10) || 0;
    agg[d].runs[r.run_id] = 1;
    if (String(r.is_gap).toUpperCase() === "TRUE") agg[d].gapRuns[r.run_id] = 1;
  });

  const isOwn = d => brandDomain && String(d).indexOf(brandDomain) >= 0;

  const all = Object.keys(agg).map(d => {
    const a = agg[d];
    const seenIn = Object.keys(a.runs).length;
    const gapIn = Object.keys(a.gapRuns).length;
    return {
      domain: d,
      answers_total: a.answers,
      runs_seen: seenIn,
      // share of runs the domain appeared in - a persistence measure
      persistence: Math.round((seenIn / runCount) * 100) / 100,
      gap_runs: gapIn,
      is_own: isOwn(d)
    };
  });

  // stable: present in at least half of the runs in the window
  const stable = all
    .filter(s => !s.is_own && s.gap_runs > 0 && s.persistence >= 0.5)
    .sort((a, b) => b.answers_total - a.answers_total)
    .slice(0, 15);

  // short history - fall back to plain volume ranking
  const fallback = all
    .filter(s => !s.is_own && s.gap_runs > 0)
    .sort((a, b) => b.answers_total - a.answers_total)
    .slice(0, 15);

  return {
    window_days: 28,
    runs_in_window: runCount,
    stable_gap_sources: stable.length ? stable : fallback,
    used_fallback: stable.length === 0,
    all_count: all.length
  };
}

