export default async function run({ execution_id, input, data, store }) {
  const get = (key, paramName) => {
    let v;
    try { v = data[key]; } catch (e) { v = undefined; }
    if (v === undefined || v === null || v === "") {
      try { v = input[paramName]; } catch (e) { v = undefined; }
    }
    return v;
  };

  const parse = v => {
    if (typeof v !== "string") return v;
    try { return JSON.parse(v); } catch (e) { return v; }
  };

  const raw = parse(get("{{$48}}", "serpRaw")) || {};
  const r = raw.result || raw;
  const organic = r.organic || r.results || [];

  const brandDomain = String(get("{{$15.value.brand_domain}}", "brandDomain") || "").toLowerCase();
  const promptId = get("{{$47.value.prompt_id}}", "promptId") || "";
  const competitors = String(get("{{$15.value.competitors}}", "competitors") || "")
    .split("|").map(s => s.trim().toLowerCase()).filter(Boolean);

  let brandPos = null;
  const compPos = {};

  (Array.isArray(organic) ? organic : []).forEach((item, i) => {
    if (!item) return;
    const link = String(item.link || item.url || "").toLowerCase();
    const title = String(item.title || "").toLowerCase();
    const pos = item.position || (i + 1);

    if (brandDomain && link.indexOf(brandDomain) >= 0 && brandPos === null) brandPos = pos;

    competitors.forEach(c => {
      const slug = c.replace(/[^a-z0-9]/g, "");
      if (!slug) return;
      if ((link.indexOf(slug) >= 0 || title.indexOf(c) >= 0) && compPos[c] === undefined) {
        compPos[c] = pos;
      }
    });
  });

  const KEY = "geo_serp_" + execution_id;
  const acc = (await store.getGlobalVariable(KEY)) || [];
  acc.push({
    prompt_id: promptId,
    brand_position: brandPos,
    in_top10: brandPos !== null,
    competitor_positions: compPos,
    results_seen: (Array.isArray(organic) ? organic.length : 0)
  });
  await store.setGlobalVariable(KEY, acc);

  return { collected: acc.length, brand_position: brandPos };
}

