export default async function run({ execution_id, store }) {
  const KEY = "geo_serp_" + execution_id;
  const acc = (await store.getGlobalVariable(KEY)) || [];
  await store.deleteGlobalVariable(KEY);

  const total = acc.length;
  const inTop = acc.filter(r => r.in_top10).length;

  let posSum = 0, posN = 0;
  acc.forEach(r => { if (r.brand_position) { posSum += r.brand_position; posN++; } });

  // prompts where Google ranks the brand but AI does not name it - the key contrast
  const ranked = acc
    .filter(r => r.in_top10)
    .map(r => ({ prompt_id: r.prompt_id, google_position: r.brand_position }))
    .sort((a, b) => a.google_position - b.google_position);

  return {
    prompts_checked: total,
    google_presence: total ? Math.round((inTop / total) * 1000) / 1000 : "",
    avg_google_position: posN ? Math.round((posSum / posN) * 10) / 10 : "",
    ranked_prompts: ranked.slice(0, 10)
  };
}

